using System.Net.Http.Json;
using System.Text.Json;
using PhoneStore.Core.Contracts;
internal sealed partial class QaSuite
{
    readonly Dictionary<string,object> scenarios=[];
    async Task Scenario(string id,object evidence){scenarios[id]=evidence;await File.WriteAllTextAsync(Path.Combine(output,"scenarios.json"),JsonSerializer.Serialize(scenarios,json));}
    async Task EndToEnd(){
        using var e2e=new QaClient(url,"E2E_CUSTOMER",requests);long user=0;
        await Check("E2E-01","Đăng ký → COD → Admin → hoàn tất → doanh thu","Một đơn mới trả đủ tiền, kho giảm1, revenue tăng đúng tổng",async()=>{
            using(var r=await anon.Send("/api/auth/register",new RegisterRequest("e2e-a",customerPassword,"Khách E2E","0955555555",null,"Địa chỉ E2E"))){Assert(r.IsSuccessStatusCode);user=(await r.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetInt64();}await e2e.Login("e2e-a",customerPassword);
            var v=await Fixture(3,1,123456.75m);var p=await ProductFor(v[0].Id);var found=await e2e.Read<Page<ProductDto>>("/api/catalog?Query="+p.Code);Assert(found.Total==1);var before=await admin.Read<ReportResult>("/api/admin/reports");var checkout=await Cart(e2e,v);var payload=JsonSerializer.SerializeToNode(checkout)!;payload["customerId"]=bId;payload["total"]=1;payload["paymentStatus"]="DA_THU";payload["role"]="ADMIN";using var placed=await e2e.Send("/api/orders",payload);Assert(placed.IsSuccessStatusCode);var o=(await placed.Content.ReadFromJsonAsync<OrderDto>())!;Assert(o.CustomerId==user&&o.Payment=="CHUA_THU"&&o.Total==checkout.Lines.Sum(x=>x.Price*x.Quantity));await Move(o.Id,"confirm");await Move(o.Id,"dispatch");await Move(o.Id,"complete");var after=await admin.Read<ReportResult>("/api/admin/reports");o=await e2e.Read<OrderDto>($"/api/orders/{o.Id}");var stock=await Stock(v[0].Id);Assert(after.Total-before.Total==123456.75m&&o.Payment=="DA_THU"&&stock.OnHand==2&&stock.Reserved==0);
            await Scenario("E2E-01",new{customerId=user,variantId=v[0].Id,initialStock=3,quantity=1,price=123456.75m,orderId=o.Id,finalStatus=o.Status,payment=o.Payment,finalStock=stock.OnHand,finalReserved=stock.Reserved,revenueDelta=after.Total-before.Total});
        });
        await Check("E2E-02","Đặt → giữ → khách hủy → đối chiếu tồn/báo cáo","Không tăng doanh thu; hoàn giữ về0",async()=>{var v=await Fixture(2);var before=await admin.Read<ReportResult>("/api/admin/reports");var o=await Place(e2e,await Cart(e2e,v));Assert((await Stock(v[0].Id)).Reserved==1);await Status(await e2e.Send($"/api/orders/{o.Id}/cancel",new TransitionRequest(o.Version,Guid.NewGuid(),"Hủy E2E")),200);var s=await Stock(v[0].Id);var after=await admin.Read<ReportResult>("/api/admin/reports");Assert(s.OnHand==2&&s.Reserved==0&&before.Total==after.Total);await Scenario("E2E-02",new{variantId=v[0].Id,orderId=o.Id,onHand=s.OnHand,reserved=s.Reserved,revenueDelta=after.Total-before.Total});});
        await Check("E2E-03","Phiếu nhập → xác nhận → mua hàng vừa nhập","Nháp0; xác nhận4; sau đặt giữ1/khả dụng3",async()=>{var v=(await Fixture(0))[0];var receipt=await Create("/api/admin/purchases",new PurchaseInput(supplier,[new(v.Id,4,321m)]));Assert((await Stock(v.Id)).OnHand==0);var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{receipt}");await Status(await admin.Send($"/api/admin/purchases/{receipt}/confirm",new TransitionRequest(p.Version,Guid.NewGuid())),200);var o=await Place(e2e,await Cart(e2e,[v]));var s=await Stock(v.Id);Assert(s.OnHand==4&&s.Reserved==1&&s.Available==3);await Scenario("E2E-03",new{receiptId=receipt,variantId=v.Id,receiptQuantity=4,cost=321m,orderId=o.Id,onHand=s.OnHand,reserved=s.Reserved,available=s.Available});});
        await Check("E2E-04","Giao thất bại → nhận lại hàng → đối chiếu","Kho chưa tăng lúc fail; nhận1lần; revenue không tăng",async()=>{var v=await Fixture(1);var before=await admin.Read<ReportResult>("/api/admin/reports");var checkout=await Cart(e2e,v);var payload=JsonSerializer.SerializeToNode(checkout)!;payload["customerId"]=bId;payload["total"]=1;payload["paymentStatus"]="DA_THU";payload["role"]="ADMIN";using var placed=await e2e.Send("/api/orders",payload);Assert(placed.IsSuccessStatusCode);var o=(await placed.Content.ReadFromJsonAsync<OrderDto>())!;Assert(o.CustomerId==user&&o.Payment=="CHUA_THU"&&o.Total==checkout.Lines.Sum(x=>x.Price*x.Quantity));await Move(o.Id,"confirm");await Move(o.Id,"dispatch");await Move(o.Id,"fail");Assert((await Stock(v[0].Id)).OnHand==0);await Move(o.Id,"return");var after=await admin.Read<ReportResult>("/api/admin/reports");var s=await Stock(v[0].Id);Assert(s.OnHand==1&&s.Reserved==0&&after.Total==before.Total);await Scenario("E2E-04",new{variantId=v[0].Id,orderId=o.Id,stockBeforeReturn=0,onHand=s.OnHand,reserved=s.Reserved,revenueDelta=after.Total-before.Total});});
        await Check("E2E-05","Khách gọi màn hình/API Admin","403; không tăng chứng từ hoặc thay đổi stock",async()=>{var before=await admin.Read<List<StockDto>>("/api/admin/stock");await Status(await e2e.Get("/api/admin/customers"),403);await Status(await e2e.Send("/api/admin/purchases",new PurchaseInput(supplier,[])),403);var after=await admin.Read<List<StockDto>>("/api/admin/stock");Assert(before.Select(x=>(x.VariantId,x.OnHand,x.Reserved)).SequenceEqual(after.Select(x=>(x.VariantId,x.OnHand,x.Reserved))));await Scenario("E2E-05",new{actor="CUSTOMER",readStatus=403,writeStatus=403,stockUnchanged=true});});
        await Check("E2E-06","Hai khách đồng thời với tồn1","Một đơn thành công, không oversell",async()=>{var v=await Fixture(1);var r1=await Cart(a,v);var r2=await Cart(b,v);var status=await Parallel(()=>a.Send("/api/orders",r1),()=>b.Send("/api/orders",r2));var s=await Stock(v[0].Id);Assert(status.Count(x=>x==200)==1&&status.Count(x=>x==409)==1&&s.OnHand==1&&s.Reserved==1&&s.Available==0);await Scenario("E2E-06",new{variantId=v[0].Id,statuses=status,onHand=s.OnHand,reserved=s.Reserved,available=s.Available});});
    }
}

